// it sits under and is empty for a holder that never asked. detail is what the
// holder says it holds, such as a host's model name; it is a claim.
type Holder struct {
	Program  string
	Account  string
	Amount   int64
	Evidence Evidence
	Lease    string
	Grant    string
	Since    string
	Detail   string
}

// capacity is bytes, 0 when the instrument cannot say. held is the sum of
// verified amounts only. instrument names what measured: windows-gpu-counters,
// linux-fdinfo, or none, in which case every holder is claimed.
type ResourceState struct {
	Resource   string
	Capacity   int64
	Held       int64
	Holders    []Holder
	Observed   string
	Instrument string
}

// state is present exactly for ok. A forbidden outcome does not reveal another
// program's rows.
type HoldersResult struct {
	Outcome ResourceCallOutcome
	State   *ResourceState
}

type ResourceList struct {
	Resources []string
	Observed  string
}

// list is present exactly for ok.
type ResourcesResult struct {
	Outcome ResourceCallOutcome
	List    *ResourceList
}

// amount is the requested admission reservation, not a physical memory quota. A
// lease not renewed by renew_by is released; the holder's bytes are then
// reported as a holder without a lease until the instrument stops seeing them.
type Lease struct {
	ID       string
	Resource string
	Amount   int64
	Since    string
	RenewBy  string
}

// One holder asked during Acquire: yielded, refused, or unanswered within the
// wait, with the reason a refusal gave.
type YieldRecord struct {
	Holder string
	Amount int64
	Answer string
	TookMs int64
}

// lease is present exactly for acquired. asked lists every holder the service
// asked to yield for this request, in order, whatever the outcome.
type AcquireResult struct {
	Outcome AcquireOutcome
	Lease   *Lease
	Asked   []YieldRecord
}

// A request that this holder give back the named lease of amount bytes of
// resource. reason names the program that asked, as rights names it.
type YieldRequest struct {
	ID       string
	Resource string
	Amount   int64
	Reason   string
	At       string
	Lease    string
}

type YieldPage struct {
	Requests []YieldRequest
	Next     string
}

// page is present exactly for ok.
type ObserveResult struct {
	Outcome ResourceCallOutcome
	Page    *YieldPage
}

type AnswerResult struct {
	Recorded bool
}

// answer is present exactly for ok.
type AnswerCallResult struct {
	Outcome ResourceCallOutcome
	Answer  *AnswerResult
}

type LeaseChange struct {
	Applied bool
	Lease   *Lease
}

// change is present exactly for ok; applied false retains the idempotent result
// for a lease not held by the caller.
type LeaseChangeResult struct {
	Outcome ResourceCallOutcome
	Change  *LeaseChange
}

// bound permits a verified child process's measured bytes to offset this
// lease's admission reservation. unverifiable and refused leave the full
// reservation in place; no process identity is published in the holder table.
type ProcessBindResult struct {
	Outcome ProcessBindOutcome
}

