func encHolder(out []byte, v *Holder, depth int) []byte {
	if !(v.Evidence).Known() {
		panic(&Refusal{Word: "bad_enum", Offset: 0})
	}
	out = append(out, '{')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "program")
	out = append(out, ':', ' ')
	out = esc(out, v.Program)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "account")
	out = append(out, ':', ' ')
	out = esc(out, v.Account)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "amount")
	out = append(out, ':', ' ')
	out = num(out, v.Amount)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "evidence")
	out = append(out, ':', ' ')
	out = esc(out, v.Evidence.String())
	if v.Lease != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "lease")
		out = append(out, ':', ' ')
		out = esc(out, v.Lease)
	}
	if v.Grant != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "grant")
		out = append(out, ':', ' ')
		out = esc(out, v.Grant)
	}
	if v.Since != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "since")
		out = append(out, ':', ' ')
		out = esc(out, writeTimestamp(v.Since))
	}
	if v.Detail != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "detail")
		out = append(out, ':', ' ')
		out = esc(out, v.Detail)
	}
	out = append(out, '\n')
	out = pad(out, depth)
	return append(out, '}')
}

